import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"姤","description":"周易正義 - 姤","frontmatter":{"title":"姤","description":"周易正義 - 姤"},"headers":[],"relativePath":"classics/zhengyi/044.md","filePath":"classics/zhengyi/044.md"}'),l={name:"classics/zhengyi/044.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>天風姤</p></blockquote><blockquote><p>卦辭：女壯，勿用取女。</p></blockquote><blockquote><p>彖曰：姤，遇也，柔遇剛也。勿用取女，不可與長也。天地相遇，品物鹹章也。剛遇中正，天下大行也。姤之時義大矣哉！</p></blockquote><h1 id="姤" tabindex="-1">姤 <a class="header-anchor" href="#姤" aria-label="Permalink to “姤”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“姤，遇也。”此卦一柔而遇五剛，故名為“姤”。施之於人，則是一女而遇五男，為壯至甚，故戒之曰“此女壯甚，勿用取此女”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="姤-遇也。柔遇剛也。-​" tabindex="-1">姤，遇也。柔遇剛也。 ​ <a class="header-anchor" href="#姤-遇也。柔遇剛也。-​" aria-label="Permalink to “姤，遇也。柔遇剛也。 ​”">​</a></h3><p>王弼：施之於人，即女遇男也。一女而遇五男，為壯至甚，故不可取也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：此就爻釋卦名，以初六一柔而上遇五剛，所以名“遇”，而用釋卦辭“女壯，勿用取女”之義也。</p><h3 id="勿用取女-不可與長也。天地相遇-品物鹹章也。-​" tabindex="-1">“勿用取女”，不可與長也。天地相遇，品物鹹章也。 ​ <a class="header-anchor" href="#勿用取女-不可與長也。天地相遇-品物鹹章也。-​" aria-label="Permalink to ““勿用取女”，不可與長也。天地相遇，品物鹹章也。 ​”">​</a></h3><p>王弼：正乃功成也。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>“勿用取女”至“品物鹹章也”。○正義曰：“勿用取女，不可與長”者，女之為體，婉娩貞順，方可期之偕老。淫壯若此，不可與之長久，故“勿用取女”。“天地相遇，品物鹹章”者，已下廣明遇義。卦得遇名，本由一柔與五剛相遇，故遇辭非美，就卦而取，遂言遇不可用，是“勿用取女”也。故孔子更就天地嘆美“遇”之為義不可廢也。天地若各亢所處，不相交遇，則萬品庶物，無由彰顯，必須二氣相遇，乃得化生，故曰：“天地相遇，品物鹹章”。</p><h3 id="剛遇中正-天下大行也。化乃大行也。-​" tabindex="-1">剛遇中正，天下大行也。化乃大行也。 ​ <a class="header-anchor" href="#剛遇中正-天下大行也。化乃大行也。-​" aria-label="Permalink to “剛遇中正，天下大行也。化乃大行也。 ​”">​</a></h3><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：莊氏雲：“一女而遇五男，既不可取，天地匹配，則能成品物。”由是言之，若剛遇中正之柔，男得幽貞之女，則天下人倫之化，乃得大行也。</p><h3 id="《姤》之時義大矣哉-​" tabindex="-1">《姤》之時義大矣哉！ ​ <a class="header-anchor" href="#《姤》之時義大矣哉-​" aria-label="Permalink to “《姤》之時義大矣哉！ ​”">​</a></h3><p>王弼：凡言義者，不盡於所見，中有意謂者也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>“姤之時義大矣哉”！正義曰：上既博美，此又結嘆，欲就卦而取義。但是一女而遇五男，不足稱美，博論“天地相遇”，乃致“品物鹹章”，然後“姤之時義大矣哉”！。○注“凡言義者”至“有意謂者也”。○正義曰：《注》總為稱義發例，故曰“凡言”也。就卦以驗名義，只是女遇於男，博尋遇之深旨，乃至道該天地，故云“不盡於所見，中有意謂”者也。</p><h2 id="《象》曰-天下有風-姤。後以施命誥四方。-​" tabindex="-1">《象》曰：天下有風，姤。後以施命誥四方。 ​ <a class="header-anchor" href="#《象》曰-天下有風-姤。後以施命誥四方。-​" aria-label="Permalink to “《象》曰：天下有風，姤。後以施命誥四方。 ​”">​</a></h2><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：風行天下，則無物不遇，故為遇象。“後以施命誥四方”者，風行草偃，天之威令，故人君法此，以施教命，誥於四方也。</p><h2 id="初六-繫於金柅-貞吉。有攸往-見兇。羸豕孚蹢躅。-​" tabindex="-1">初六：繫於金柅，貞吉。有攸往，見兇。羸豕孚蹢躅。 ​ <a class="header-anchor" href="#初六-繫於金柅-貞吉。有攸往-見兇。羸豕孚蹢躅。-​" aria-label="Permalink to “初六：繫於金柅，貞吉。有攸往，見兇。羸豕孚蹢躅。 ​”">​</a></h2><p>王弼：金者，堅剛之物。尼者，制動之主，謂九四也。初六處遇之始，以一柔而承五剛，體夫躁質，得遇而通，散而無主，自縱者也。柔之為物，不可以不牽。臣妾之道，不可以不貞，故必繫於正應，乃得“貞吉”也。若不牽於一，而有攸往行，則唯兇是見矣。羸豕，謂牝豕也。群豕之中，豭強而牝弱，故謂之“羸豕”也。孚，猶務躁也。夫陰質而躁恣者，羸豕特甚焉，言以不貞之陰，失其所牽，其為淫醜，若羸豕之孚務蹢躅也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>“初六繫於金柅”至“羸豕孚蹢躅”。○正義曰：繫於金柅，貞吉”者，金者，堅剛之物。柅者，制動之主，謂九四也。初六陰質，若系於正，應以從於四，則貞而吉矣，故曰“繫於金柅，貞吉”也。“有攸往，見兇”者，若不牽於一，而有所行往，則惟兇是見矣，故曰“有攸往，見兇”。“羸豕孚蹢躅”者，初六處遇之初，以一柔而承五剛，是不繫金柅，有所往者也。不繫而往，則如羸豕之務躁而蹢躅然也，故曰：“羸豕孚蹢躅”。羸豕謂牝豕也。群豕之中，豭強而牝弱也，故謂牝豕為羸豕。陰質而淫躁，牝豕特甚焉，故取以為喻。○注“柅者，制動之主”。○正義曰：“柅者，制動之主”。柅之為物，眾說不同。王肅之徒皆為織績之器，婦人所用。惟馬雲：“柅者，在車之下，所以止輪令不動者也。”王注云：“柅，制動之主。”蓋與馬同。</p><h3 id="《象》曰-繫於金柅-柔道牽也。-​" tabindex="-1">《象》曰：“繫於金柅”，柔道牽也。 ​ <a class="header-anchor" href="#《象》曰-繫於金柅-柔道牽也。-​" aria-label="Permalink to “《象》曰：“繫於金柅”，柔道牽也。 ​”">​</a></h3><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“柔道牽”者，陰柔之道，必須有所牽繫也。</p><h2 id="九二-包有魚-無咎-不利賓。-​" tabindex="-1">九二：包有魚，無咎，不利賓。 ​ <a class="header-anchor" href="#九二-包有魚-無咎-不利賓。-​" aria-label="Permalink to “九二：包有魚，無咎，不利賓。 ​”">​</a></h2><p>王弼：初陰而窮下，故稱“魚”。不正之陰，處遇之始，不能逆近者也。初自樂來應已之廚，非為犯奪，故“無咎”也。擅人之物，以為已惠，義所不為，故“不利賓”也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“庖有魚、無咎”者，初六以陰而處下，故稱魚也。以不正之陰，處遇之始，不能逆於所近，故舍九四之正應，樂充九二之庖廚，故曰“九二、庖有魚”。初自樂來，為已之廚，非為犯奪，故得“無咎”也。“不利賓者”，夫擅人之物，以為己惠，義所不為，故“不利賓”也。</p><h3 id="《象》曰-包有魚-義不及賓也。-​" tabindex="-1">《象》曰：“包有魚”，義不及賓也。 ​ <a class="header-anchor" href="#《象》曰-包有魚-義不及賓也。-​" aria-label="Permalink to “《象》曰：“包有魚”，義不及賓也。 ​”">​</a></h3><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“義不及賓”者，言有他人之物，於義不可及賓也。</p><h2 id="九三-臀無膚-其行次且-厲-無大咎。-​" tabindex="-1">九三：臀無膚，其行次且，厲，無大咎。 ​ <a class="header-anchor" href="#九三-臀無膚-其行次且-厲-無大咎。-​" aria-label="Permalink to “九三：臀無膚，其行次且，厲，無大咎。 ​”">​</a></h2><p>王弼：處下體之極，而二據於初，不為已乘，居不獲安，行為其應，不能牽據，以固所處，故曰“臀無膚，其行次且”也。然履得其位，非為妄處，不遇其時，故使危厲。災非已招，是以“無大咎”也。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：陽之所據者，陰也。九三處下體之上，為內卦之主，以乘於二，無陰可據，居不獲安，上又無應，不能牽據以固所處，同於夬卦九四之失據，故曰“臀無膚，其行次且”也。然復得其位，非為妄處，特以不遇其時，故致此危厲，災非已招，故無大咎，故曰“厲無大咎”。</p><h3 id="《象》曰-其行次且-行未牽也。-​" tabindex="-1">《象》曰：“其行次且”，行未牽也。 ​ <a class="header-anchor" href="#《象》曰-其行次且-行未牽也。-​" aria-label="Permalink to “《象》曰：“其行次且”，行未牽也。 ​”">​</a></h3><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“行未牽”者，未能牽據，故“其行次且”，是“行未牽也”。</p><h2 id="九四-包無魚-起兇。-​" tabindex="-1">九四：包無魚，起兇。 ​ <a class="header-anchor" href="#九四-包無魚-起兇。-​" aria-label="Permalink to “九四：包無魚，起兇。 ​”">​</a></h2><p>王弼：二有其魚，故失之也。無民而動，失應而作，是以“兇”也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“庖無魚”者，二擅其應，故曰“庖無魚”也。庖之無魚，則是無民之義也。“起兇”者，起，動也。“無民而動，失應而作，是以兇也。”</p><h3 id="《象》曰-無魚-之兇-遠民也。-​" tabindex="-1">《象》曰：“無魚”之兇，遠民也。 ​ <a class="header-anchor" href="#《象》曰-無魚-之兇-遠民也。-​" aria-label="Permalink to “《象》曰：“無魚”之兇，遠民也。 ​”">​</a></h3><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“遠民”者，陰為陽之民，為二所據，故曰“遠民”也。</p><h2 id="九五-以杞包瓜-含章-有隕自天。-​" tabindex="-1">九五：以杞包瓜，含章，有隕自天。 ​ <a class="header-anchor" href="#九五-以杞包瓜-含章-有隕自天。-​" aria-label="Permalink to “九五：以杞包瓜，含章，有隕自天。 ​”">​</a></h2><p>王弼：杞之為物，生於肥地者也。包瓜為物，繫而不食者也。九五履得尊位，而不遇其應，得地而不食，含章而未發，不遇其應，命未流行。然處得其所，體剛居中，志不捨命，不可傾隕，故曰“有隕自天”也。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>“九五以杞包瓜”至“有隕自天”。○正義曰：“以杞匏瓜”者，杞之為物，生於肥地；匏瓜為物，繫而不食，九五處得尊位而不遇，其應是得地而不食，故曰“以杞匏瓜”也。“含章，有隕自天”者，不遇其應，命未流行，無物發起其美，故曰“含章”。然體剛居中，雖復當位，命未流行，而不能改其操，無能傾隕之者，故曰：“有隕自天”，蓋言惟天能隕之耳。○注“杞之為物，生於肥地者也”。○正義曰：“杞之為物，生於肥地者也”，先儒說杞，亦有不同。馬雲：“杞，大木也。”《左傳》雲：“杞梓皮革自楚注，則為杞梓之杞。”子夏《傳》曰：“作杞匏瓜。”薛虞《記》雲：“杞，杞柳也。杞性柔刃，宜屈橈，似匏瓜。”又為杞柳之杞。案：王氏雲“生於肥地”，蓋以杞為今之枸杞也。</p><h3 id="《象》曰-九五-含章-中正也。-有隕自天-志不捨命也。-​" tabindex="-1">《象》曰：九五“含章”，中正也。“有隕自天”，志不捨命也。 ​ <a class="header-anchor" href="#《象》曰-九五-含章-中正也。-有隕自天-志不捨命也。-​" aria-label="Permalink to “《象》曰：九五“含章”，中正也。“有隕自天”，志不捨命也。 ​”">​</a></h3><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“中正”者，中正故有美，無應故“含章”，而不發。若非九五中正，則無美可含，故舉爻位而言“中正”也。“志不捨命”者，雖命未流行，而居尊當位，“志不捨命”，故曰“不可傾隕”也。</p><h2 id="上九-姤其角-吝-無咎。-​" tabindex="-1">上九：姤其角，吝，無咎。 ​ <a class="header-anchor" href="#上九-姤其角-吝-無咎。-​" aria-label="Permalink to “上九：姤其角，吝，無咎。 ​”">​</a></h2><p>王弼：進之於極，無所復遇，遇角而已，故曰“姤其角”也。進而無遇，獨恨而已，不與物爭，其道不害，故無兇咎也。</p><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“姤其角”者，角者，最處體上，上九進之於極，無所復遇，遇角而已，故曰“姤其角”也。“吝無咎”者，角非所安，與無遇等，故獨恨而鄙吝也。然不與物爭，其道不害，故無兇咎，故曰“無咎”也。</p><h3 id="《象》曰-姤其角-上窮吝也。-​" tabindex="-1">《象》曰：“姤其角”，上窮吝也。 ​ <a class="header-anchor" href="#《象》曰-姤其角-上窮吝也。-​" aria-label="Permalink to “《象》曰：“姤其角”，上窮吝也。 ​”">​</a></h3><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“上窮吝”者，處於上窮，所以遇角而吝也。</p>',67)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
